// Redis'teki sohbet geçmişini chat penceresine geri yüklemek için süzer.
// Hafızada araç çağrıları ve belge parçaları da duruyor; ekranda yalnızca
// ziyaretçinin mesajları ve botun metin cevapları görünmeli.
const ham = $input.first().json.gecmis || [];
const data = ham
  .slice()
  .reverse() // Redis listesi en yeniden eskiye; pencere eskiden yeniye ister
  .map((satir) => {
    try { return JSON.parse(satir); } catch { return null; }
  })
  .filter((m) => m && (m.type === 'human' || m.type === 'ai'))
  .filter((m) => typeof m.data?.content === 'string' && m.data.content.trim() !== '')
  .map((m) => ({
    lc: 1,
    type: 'constructor',
    id: ['langchain_core', 'messages', m.type === 'human' ? 'HumanMessage' : 'AIMessage'],
    kwargs: { content: m.data.content },
  }));
return [{ json: { data } }];
